export const Pagination: Story = {
  render: PaginationExample,
  parameters: { sourceCode: 'import { Flex } from \'@semcore/ui/base-components\';\nimport { DataTable } from \'@semcore/ui/data-table\';\nimport Pagination from \'@semcore/ui/pagination\';\nimport Select from \'@semcore/ui/select\';\nimport React from \'react\';\n\nconst Demo = () => {\n  const [limit, setLimit] = React.useState(10);\n  const [currentPage, setCurrentPage] = React.useState(0);\n  const numberFormat = React.useMemo(() => new Intl.NumberFormat(\'en-US\'), []);\n  const currencyFormat = React.useMemo(\n    () => new Intl.NumberFormat(\'en-US\', { currency: \'USD\', style: \'currency\' }),\n    [],\n  );\n\n  const numLim = Number(limit);\n  const tableData: typeof data = [];\n\n  let index = 0;\n\n  for (let i = 0; i < 10; i++) {\n    tableData.push(...data.map((item) => {\n      index++;\n\n      return {\n        ...item,\n        keyword: `${index} ${item.keyword}`,\n      };\n    }));\n  }\n\n  return (\n    <>\n      <DataTable\n        data={tableData.slice(currentPage * numLim, currentPage * numLim + numLim)}\n        aria-label=\'Pagination\'\n        h=\'auto\'\n        columns={[\n          { name: \'keyword\', children: \'Keyword\', justifyContent: \'left\' },\n          {\n            name: \'kd\',\n            children: \'KD %\',\n            justifyContent: \'right\',\n            gtcWidth: \'minmax(fit-content, 68px)\',\n          },\n          { name: \'cpc\', children: \'CPC\', gtcWidth: \'minmax(fit-content, 60px)\' },\n          {\n            name: \'vol\',\n            children: \'Vol.\',\n            gtcWidth: \'minmax(fit-content, 120px)\',\n            justifyContent: \'left\',\n          },\n        ]}\n        renderCell={(props) => {\n          const { column, row } = props;\n\n          if (!row) return props.defaultRender();\n\n          const value = row[column.name];\n\n          if (column.name === \'keyword\') {\n            return props.defaultRender();\n          }\n\n          if (typeof value !== \'number\' || value === -1) {\n            return \'n/a\';\n          }\n\n          if (column.name === \'cpc\') {\n            return currencyFormat.format(value);\n          }\n\n          return numberFormat.format(value);\n        }}\n      />\n      <Flex gap={4} mt={4}>\n        <Pagination\n          totalPages={Math.ceil(tableData.length / numLim)}\n          currentPage={currentPage + 1}\n          onCurrentPageChange={(page) => setCurrentPage(page - 1)}\n        />\n        <Select\n          aria-label=\'Table rows on the page\'\n          value={numLim}\n          onChange={setLimit}\n          options={[{ value: 3, children: 3 }, { value: 5, children: 5 }, { value: 8, children: 8 }, { value: 10, children: 10 }]}\n        />\n      </Flex>\n    </>\n  );\n};\n\nexport default Demo;\n\nconst data = [\n  {\n    keyword: \'ebay buy\',\n    kd: 77.8,\n    cpc: 1.25,\n    vol: 32500000,\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: 11.2,\n    cpc: 3.4,\n    vol: 65457920,\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: 10,\n    cpc: 0.65,\n    vol: 47354640,\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: -1,\n    cpc: 0,\n    vol: -1,\n  },\n  {\n    keyword: \'ebay buy last\',\n    kd: 75.89,\n    cpc: 0,\n    vol: 21644290,\n  },\n];\n' },
  parameters: { sourceCode: 'import { Flex } from \'@semcore/ui/base-components\';\nimport { DataTable } from \'@semcore/ui/data-table\';\nimport Pagination from \'@semcore/ui/pagination\';\nimport Select from \'@semcore/ui/select\';\nimport React from \'react\';\n\nconst Demo = () => {\n  const [limit, setLimit] = React.useState(10);\n  const [currentPage, setCurrentPage] = React.useState(0);\n  const numberFormat = React.useMemo(() => new Intl.NumberFormat(\'en-US\'), []);\n  const currencyFormat = React.useMemo(\n    () => new Intl.NumberFormat(\'en-US\', { currency: \'USD\', style: \'currency\' }),\n    [],\n  );\n\n  const numLim = Number(limit);\n  const tableData: typeof data = [];\n\n  let index = 0;\n\n  for (let i = 0; i < 10; i++) {\n    tableData.push(...data.map((item) => {\n      index++;\n\n      return {\n        ...item,\n        keyword: `${index} ${item.keyword}`,\n      };\n    }));\n  }\n\n  return (\n    <>\n      <DataTable\n        data={tableData.slice(currentPage * numLim, currentPage * numLim + numLim)}\n        aria-label=\'Pagination\'\n        h=\'auto\'\n        columns={[\n          { name: \'keyword\', children: \'Keyword\', justifyContent: \'left\' },\n          {\n            name: \'kd\',\n            children: \'KD %\',\n            justifyContent: \'right\',\n            gtcWidth: \'minmax(fit-content, 68px)\',\n          },\n          { name: \'cpc\', children: \'CPC\', gtcWidth: \'minmax(fit-content, 60px)\' },\n          {\n            name: \'vol\',\n            children: \'Vol.\',\n            gtcWidth: \'minmax(fit-content, 120px)\',\n            justifyContent: \'left\',\n          },\n        ]}\n        renderCell={(props) => {\n          const { column, row } = props;\n\n          if (!row) return props.defaultRender();\n\n          const value = row[column.name];\n\n          if (column.name === \'keyword\') {\n            return props.defaultRender();\n          }\n\n          if (typeof value !== \'number\' || value === -1) {\n            return \'n/a\';\n          }\n\n          if (column.name === \'cpc\') {\n            return currencyFormat.format(value);\n          }\n\n          return numberFormat.format(value);\n        }}\n      />\n      <Flex gap={4} mt={4}>\n        <Pagination\n          totalPages={Math.ceil(tableData.length / numLim)}\n          currentPage={currentPage + 1}\n          onCurrentPageChange={(page) => setCurrentPage(page - 1)}\n        />\n        <Select\n          aria-label=\'Table rows on the page\'\n          value={numLim}\n          onChange={setLimit}\n          options={[{ value: 3, children: 3 }, { value: 5, children: 5 }, { value: 8, children: 8 }, { value: 10, children: 10 }]}\n        />\n      </Flex>\n    </>\n  );\n};\n\nexport default Demo;\n\nconst data = [\n  {\n    keyword: \'ebay buy\',\n    kd: 77.8,\n    cpc: 1.25,\n    vol: 32500000,\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: 11.2,\n    cpc: 3.4,\n    vol: 65457920,\n  },\n  {\n    keyword: \'www.ebay.com\',\n    kd: 10,\n    cpc: 0.65,\n    vol: 47354640,\n  },\n  {\n    keyword: \'ebay buy\',\n    kd: -1,\n    cpc: 0,\n    vol: -1,\n  },\n  {\n    keyword: \'ebay buy last\',\n    kd: 75.89,\n    cpc: 0,\n    vol: 21644290,\n  },\n];\n' },
};
